{
  "definition_simple": "A talk or demonstration showing something to a group of people.",
  "definition_standard": "The act of presenting something, such as a speech, report, or display, to an audience.",
  "pos": "noun",
  "semantic_class": "abstract",
  "sentences": [
    {"sentence": "I enjoy watching presentations.", "tier": "T1"},
    {"sentence": "She has many presentations to do.", "tier": "T1"},
    {"sentence": "The students gave presentations on their projects.", "tier": "T2"},
    {"sentence": "His presentations are always clear.", "tier": "T2"},
    {"sentence": "These presentations include charts and graphs.", "tier": "T3"},
    {"sentence": "We attended three presentations this morning.", "tier": "T3"},
    {"sentence": "The marketing team delivered compelling presentations to the investors.", "tier": "T4"},
    {"sentence": "To succeed, your presentations must address audience concerns.", "tier": "T4"},
    {"sentence": "Despite long preparation, some presentations fail to convey the core message.", "tier": "T5"},
    {"sentence": "In academic contexts, presentations are often evaluated on both content and delivery style.", "tier": "T6"}
  ],
  "morphological_forms": [
    {"label": "singular", "form": "presentation"},
    {"label": "plural", "form": "presentations"}
  ],
  "morphology_wrong_forms": [
    {
      "form": "presantation",
      "explanation": "Missing the 'e' after 's' – a common spelling error due to vowel reduction."
    },
    {
      "form": "presentationn",
      "explanation": "Doubled 'n' at the end – overgeneralization of the rule for doubling final consonants."
    },
    {
      "form": "prezentation",
      "explanation": "Replacing 's' with 'z' – phonetic spelling influenced by the pronunciation of the first syllable."
    },
    {
      "form": "presentation's",
      "explanation": "Using an apostrophe for plural – confusion between plural and possessive forms."
    },
    {
      "form": "presentationes",
      "explanation": "Adding '-es' like in Spanish – native Spanish speakers may transfer this pattern."
    },
    {
      "form": "presentationss",
      "explanation": "Double 's' at the end – overemphasis on the final /z/ sound."
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "presentation",
      "explanation": "The singular form lacks the final /z/ sound, causing confusion in number."
    },
    {
      "word": "prestations",
      "explanation": "Differing by the consonant cluster /st/ instead of /zən/ and a slight vowel change, leading to mishearing."
    },
    {
      "word": "presentiments",
      "explanation": "Similar onset and stress pattern, but differs in the middle syllables (/zɛntɪm/ vs /zənˈteɪ/), causing auditory confusion."
    }
  ],
  "primary_collocate": "give",
  "collocation_distractors": [
    {
      "word": "perform",
      "explanation": "Perform implies a theatrical act, not a professional or academic talk."
    },
    {
      "word": "show",
      "explanation": "Show suggests displaying an object, not delivering a talk."
    },
    {
      "word": "display",
      "explanation": "Display is used for visual exhibitions, not verbal presentations."
    }
  ],
  "collocation_wrong_collocate": {
    "word": "conduct",
    "explanation": "Conduct is used with meetings, research, or experiments, not standard for presentations."
  },
  "cloze_distractors": [
    {
      "sentence": "The marketing team ______ compelling presentations to the investors.",
      "correct_answer": "delivered",
      "distractor": "performed",
      "reason": "Performed suggests a theatrical performance, not a business presentation."
    },
    {
      "distractor": "displayed",
      "reason": "Displayed implies showing an object, not giving a talk."
    },
    {
      "distractor": "announced",
      "reason": "Announced is for short statements, not detailed presentations."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "She made a presentations to the board.",
      "reason": "Number agreement error: 'a' requires a singular noun, but 'presentations' is plural."
    },
    {
      "sentence": "I enjoyed the presentations of the book.",
      "reason": "Wrong argument structure: 'presentations of' is not idiomatic; use 'presentation of' (singular) or 'presentations about'."
    },
    {
      "sentence": "The presentations were very long that I fell asleep.",
      "reason": "Wrong register/degree structure: requires 'so long that' instead of 'very long that'."
    }
  ],
  "spot_incorrect": {
    "sentence": "The presentations were very interested.",
    "error_description": "Wrong adjective form: 'interested' is used for people, but the presentations are the subject; should be 'interesting'.",
    "corrected_sentence": "The presentations were very interesting."
  },
  "word_family_forms": ["present (verb)", "presenter (noun)", "presentational (adjective)", "presentationally (adverb)"],
  "word_family_fake_forms": ["presentationist", "presentationize", "presentationless"],
  "syn_ant_candidates": [
    {"word": "lectures", "type": "synonym"},
    {"word": "speeches", "type": "synonym"},
    {"word": "demonstrations", "type": "synonym"},
    {"word": "talks", "type": "synonym"}
  ],
